package com.acme.tenant.handler;

import javax.inject.Inject;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.HeaderParam;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;

import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Base64;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.sql.DataSource;

import org.jboss.logging.Logger;

@Path("/api/v2/tenant-data")
public class TenantDataHandler {

    private static final Logger LOG = Logger.getLogger(TenantDataHandler.class);

    @Inject
    DataSource dataSource;

    @POST
    @Path("/import")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response importData(
            @HeaderParam("X-Tenant-ID") String tenantId,
            ImportRequest request) {

        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(400).entity("{\"error\":\"Missing tenant ID\"}").build();
        }

        try {
            // Set tenant context for RLS enforcement
            try (Connection conn = dataSource.getConnection()) {
                PreparedStatement setCtx = conn.prepareStatement(
                    "SET app.current_tenant = ?");
                setCtx.setString(1, tenantId);
                setCtx.execute();

                // Deserialize the payload object for bulk import
                Object importPayload = deserializePayload(request.getSerializedData());

                // Process the deserialized import batch
                if (importPayload instanceof TenantBatchImport) {
                    TenantBatchImport batch = (TenantBatchImport) importPayload;
                    int count = processBatch(conn, batch, tenantId);
                    return Response.ok("{\"imported\":" + count + "}").build();
                } else {
                    return Response.status(400)
                        .entity("{\"error\":\"Invalid payload type\"}").build();
                }
            }
        } catch (Exception e) {
            LOG.error("Import failed for tenant: " + tenantId, e);
            return Response.status(500)
                .entity("{\"error\":\"Internal error\"}").build();
        }
    }

    private Object deserializePayload(String base64Data) throws Exception {
        byte[] data = Base64.getDecoder().decode(base64Data);
        // ObjectInputStream used for backward compat with legacy import clients
        try (ObjectInputStream ois = new ObjectInputStream(
                new ByteArrayInputStream(data))) {
            return ois.readObject();
        }
    }

    private int processBatch(Connection conn, TenantBatchImport batch, String tenantId)
            throws Exception {
        int count = 0;
        PreparedStatement ps = conn.prepareStatement(
            "INSERT INTO tenant_records (tenant_id, record_key, record_value) VALUES (?, ?, ?)");
        for (TenantRecord record : batch.getRecords()) {
            ps.setString(1, tenantId);
            ps.setString(2, record.getKey());
            ps.setString(3, record.getValue());
            ps.addBatch();
            count++;
        }
        ps.executeBatch();
        return count;
    }

    @POST
    @Path("/query")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response queryData(
            @HeaderParam("X-Tenant-ID") String tenantId,
            QueryRequest request) {

        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(400).entity("{\"error\":\"Missing tenant ID\"}").build();
        }

        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement setCtx = conn.prepareStatement(
                "SET app.current_tenant = ?");
            setCtx.setString(1, tenantId);
            setCtx.execute();

            PreparedStatement ps = conn.prepareStatement(
                "SELECT record_key, record_value FROM tenant_records WHERE record_key LIKE ?");
            ps.setString(1, request.getPattern());
            ResultSet rs = ps.executeQuery();

            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) sb.append(",");
                sb.append("{\"key\":\"")
                  .append(rs.getString(1))
                  .append("\",\"value\":\"")
                  .append(rs.getString(2))
                  .append("\"}");
                first = false;
            }
            sb.append("]");
            return Response.ok(sb.toString()).build();
        } catch (Exception e) {
            LOG.error("Query failed for tenant: " + tenantId, e);
            return Response.status(500)
                .entity("{\"error\":\"Internal error\"}").build();
        }
    }
}
